    @Test
    public void testNone() {
        Safelist safelist = Safelist.none();
        assertFalse(safelist.isSafeTag("a"));
    }

    @Test
    public void testSimpleText() {
        Safelist safelist = Safelist.simpleText();
        assertFalse(safelist.isSafeTag("a"));
    }

    @Test
    public void testBasic() {
        Safelist safelist = Safelist.basic();
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeAttribute("href", "https://www.example.com"));
        assertTrue(safelist.getEnforcedAttributes("img") != null);
    }

    @Test
    public void testBasicWithImages() {
        Safelist safelist = Safelist.basicWithImages();
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeAttribute("href", "https://www.example.com"));
        assertTrue(safelist.getEnforcedAttributes("img") != null);
    }

    @Test
    public void testRelaxed() {
        Safelist safelist = Safelist.relativelySafe();
        assertFalse(safelist.isSafeTag("a"));
    }

    @Test
    public void testNoTags() {
        Safelist safelist = Safelist.none();
        assertFalse(safelist.addTags("a", "b", "c"));
    }

    @Test
    public void testAddTagsWithoutAttribute() {
        Safelist safelist = Safelist.relativelySafe();
        assertTrue(safelist.removeAttributes("tag"));
        assertFalse(safelist.removeAttributes(null));
    }

    @Test
    public void testRemoveTags() {
        Safelist safelist = Safelist.relativelySafe();
        assertTrue(safelist.addTags("a", "b", "c"));
        assertFalse(safelist.removeTags("d", "e", "f"));
    }

    @Test
    public void testAddAttributesWithoutTag() {
        Safelist safelist = Safelist.relativelySafe();
        assertTrue(safelist.addAttributes("href", "https://www.example.com", "title"));
    }

    @Test
    public void testRemoveAttributesWithoutTag() {
        Safelist safelist = Safelist.relativelySafe();
        assertTrue(safelist.removeAttributes("tag", "class"));
        assertFalse(safelist.removeAttributes(null));
    }

    @Test
    public void testAddEnforcedAttribute() {
        Safelist safelist = Safelist.relativelySafe();
        Safelist.Safelist.EnforceEnforcedAttribute s = Safelist.addEnforcedAttribute("href", "https://www.example.com", "title");
        assertTrue(s.isSafeTag("a") && s.getEnforcedAttributes("tag").containsKey("title"));
    }

    @Test
    public void testRemoveEnforcedAttribute() {
        Safelist safelist = Safelist.relativelySafe();
        Safelist.Safelist.EnforceEnforcedAttribute s = Safelist.addEnforcedAttribute("href", "https://www.example.com", "title");
        assertTrue(s.removeEnforcedAttribute("tag") && s.getEnforcedAttributes("tag").containsKey("title"));
    }

    @Test
    public void testPreserveRelativeLinks() {
        Safelist safelist = Safelist.preserveRelativeLinks(true);
        assertTrue(Safelist.Safelist.isSafeTag("a"));
        assertFalse(Safelist.Safelist.isSafeTag("img"));
    }
